export const t = (key, params) => {
    const out = rawT(key, params);
    if (!out.includes('[['))
        return out;
    return out.replace(/\[\[([A-Za-z0-9_.-]+):([^|\]]+)\|([^\]]+)\]\]/g, (_m, k, one, other) => {
        const v = params?.[k];
        const n = typeof v === 'number' ? v : Number(String(v ?? '').replace(/,/g, ''));
        return n === 1 ? one : other;
    });
};
